function n(t,o=2){if(!Number.isFinite(t))return"—";const r=Math.abs(t),i=t<0?"-":"";return r>=1e9?`${i}$${(r/1e9).toFixed(2)}B`:r>=1e6?`${i}$${(r/1e6).toFixed(2)}M`:i+new Intl.NumberFormat("en-US",{style:"currency",currency:"USD",minimumFractionDigits:o,maximumFractionDigits:o}).format(r)}function a(t,o=2){return`${t>0?"+":""}${t.toFixed(o)}%`}function m(t){return Number.isFinite(t)?t>=1e3?t.toLocaleString("en-US",{minimumFractionDigits:2,maximumFractionDigits:2}):t>=1?t.toFixed(4):t.toFixed(t>0?Math.min(12,Math.max(6,-Math.floor(Math.log10(t))+3)):6):"—"}function u(t){const o=Date.now()-new Date(t).getTime(),r=Math.floor(o/1e3);if(r<60)return`${r}s ago`;const i=Math.floor(r/60);if(i<60)return`${i}m ago`;const e=Math.floor(i/60);return e<24?`${e}h ago`:`${Math.floor(e/24)}d ago`}export{m as a,a as b,n as f,u as t};
